 protected override bool ProcessCmdKey(ref Message message,Keys key){if(FormatRequested!=null&&(key==(Keys.Control|Keys.B)||key==(Keys.Control|Keys.I))){FormatRequested((key&Keys.KeyCode)==Keys.B?TextEmphasis.Bold:TextEmphasis.Italic);return true;}if(key==Keys.Enter||key==Keys.Escape){if(EndRequested!=null)EndRequested(key==Keys.Enter);return true;}return base.ProcessCmdKey(ref message,key);}
}
public partial class MainForm {
 TextBox inlineText;Font inlineFont;LabelSettings textEditBefore;int textEditIndex=-1,inspectedTextIndex=-1;bool textEditWasDirty,endingTextEdit;
