 void PositionInlineText(){if(inlineText==null||textEditIndex<0||preview.Settings==null)return;var text=preview.Settings.Texts[textEditIndex];var element=preview.Element(textEditIndex);var corners=ElementTransform.Corners(element);float left=float.MaxValue,top=float.MaxValue,right=float.MinValue,bottom=float.MinValue;foreach(var corner in corners){var point=preview.ScreenPoint(corner);left=Math.Min(left,point.X);right=Math.Max(right,point.X);top=Math.Min(top,point.Y);bottom=Math.Max(bottom,point.Y);}int x=Math.Max(0,Math.Min(Math.Max(0,preview.ClientSize.Width-80),(int)Math.Floor(left))),y=Math.Max(0,Math.Min(Math.Max(0,preview.ClientSize.Height-30),(int)Math.Floor(top)));inlineText.Bounds=new Rectangle(x,y,Math.Max(40,Math.Min(Math.Max(80,(int)Math.Ceiling(right-left)+6),preview.ClientSize.Width-x)),Math.Max(24,Math.Min(Math.Max(30,(int)Math.Ceiling(bottom-top)+6),preview.ClientSize.Height-y)));float size=(float)Math.Max(12,Math.Min(64,text.Size*25.4/72*preview.LabelRectangle().Width/preview.Settings.Width));if(inlineFont==null||Math.Abs(inlineFont.Size-size)>.1){var old=inlineFont;inlineFont=new Font(text.FontName,size,text.Bold?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Pixel);inlineText.Font=inlineFont;if(old!=null)old.Dispose();}}
